def find_anagrams(s, p):
    n, m = len(s), len(p)
    p_count = {}
    for ch in p:
        p_count[ch] = p_count.get(ch, 0) + 1
    result = []
    for i in range(n - m + 1):
        window_count = {}
        for ch in s[i:i + m]:                                    # recount this window's letters from scratch
            window_count[ch] = window_count.get(ch, 0) + 1
        if window_count == p_count:
            result.append(i)
    return result


if __name__ == "__main__":
    s = "cbaebabacd"
    p = "abc"
    print(find_anagrams(s, p))

