import java.util.*;

public class Main {
    List<Integer> findAnagrams(String s, String p) {
        int n = s.length(), m = p.length();
        Map<Character, Integer> pCount = new HashMap<>();
        for (char ch : p.toCharArray()) pCount.merge(ch, 1, Integer::sum);
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i <= n - m; i++) {
            Map<Character, Integer> windowCount = new HashMap<>();
            for (int j = i; j < i + m; j++) {                           // recount this window's letters from scratch
                windowCount.merge(s.charAt(j), 1, Integer::sum);
            }
            if (windowCount.equals(pCount)) result.add(i);
        }
        return result;
    }

    public static void main(String[] args) {
        String s = "cbaebabacd";
        String p = "abc";
        Main solution = new Main();
        System.out.println(solution.findAnagrams(s, p));
    }
}

