vector<int> findAnagrams(string s, string p) {
    int n = (int)s.size(), m = (int)p.size();
    vector<int> result;
    if (m > n) return result;
    int pCount[26] = {0}, windowCount[26] = {0};
    for (char ch : p) pCount[ch - 'a']++;
    for (int i = 0; i < n; i++) {
        windowCount[s[i] - 'a']++;                                     // add the newly included character
        if (i >= m) {
            windowCount[s[i - m] - 'a']--;                                 // remove the character that fell out
        }
        if (i >= m - 1 && equal(begin(windowCount), end(windowCount), begin(pCount))) {
            result.push_back(i - m + 1);
        }
    }
    return result;
}

